#!/usr/bin/env python3
"""One-off read-only audit evidence extractor; output only to supplied temp directory."""
import argparse
import collections
import csv
import hashlib
import json
from pathlib import Path
import re
import subprocess
import time

def digest(s):
    return hashlib.sha256(s.encode('utf-8')).hexdigest()

def write_json(path, obj):
    path.write_text(json.dumps(obj, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')

def main():
    p = argparse.ArgumentParser()
    p.add_argument('--root', required=True)
    p.add_argument('--output', required=True)
    a = p.parse_args()
    root, out = Path(a.root).resolve(), Path(a.output).resolve()
    if out.is_relative_to(root):
        raise SystemExit('Evidence output must be outside repository')
    out.mkdir(parents=True, exist_ok=True)
    start = time.perf_counter()
    status = lambda: subprocess.check_output(['git', '-C', str(root), 'status', '--short'], text=True)
    before = status()
    head = subprocess.check_output(['git','-C',str(root),'rev-parse','HEAD'],text=True).strip()
    files, records = [], []
    for path in sorted((root/'openspec/specs').glob('**/spec.md'), key=lambda x: x.relative_to(root).as_posix()):
        rel = path.relative_to(root).as_posix()
        data = path.read_bytes()
        text = data.decode('utf-8')
        lines = text.splitlines(keepends=True)
        headings, warnings, fence = [], [], None
        for i, line in enumerate(lines, 1):
            stripped = line.rstrip('\r\n')
            fm = re.match(r'^ {0,3}(`{3,}|~{3,})(.*)$', stripped)
            if fm:
                mark = fm.group(1)
                if fence is None:
                    fence = (mark[0], len(mark), i)
                elif mark[0] == fence[0] and len(mark) >= fence[1] and not fm.group(2).strip():
                    fence = None
                continue
            hm = re.match(r'^( {0,3})(#{1,6})[ \t]+(.*?)[ \t]*$', stripped)
            if fence:
                if hm and re.search(r'(Requirement|Scenario):', hm.group(3)):
                    warnings.append({'kind':'fenced_normative_heading_ignored','line':i})
                continue
            if hm:
                title = re.sub(r'[ \t]+#+[ \t]*$', '', hm.group(3))
                headings.append({'level':len(hm.group(2)), 'title':title, 'raw':line, 'line':i})
                if re.match(r'^(Requirement|Scenario):', title):
                    expected = 3 if title.startswith('Requirement:') else 4
                    if len(hm.group(2)) != expected:
                        warnings.append({'kind':'unexpected_normative_heading_level','line':i,'expected':expected})
            elif re.search(r'^\s*(?:[-*+]\s+|>\s*)?#+\s*(Requirement|Scenario):', stripped):
                warnings.append({'kind':'nested_or_malformed_normative_heading','line':i})
        if fence:
            warnings.append({'kind':'unclosed_fence','line':fence[2]})
        def raw(lo, hi):
            return ''.join(lines[lo-1:hi])
        reqs = [h for h in headings if h['level']==3 and h['title'].startswith('Requirement:')]
        scenarios = [h for h in headings if h['level']==4 and h['title'].startswith('Scenario:')]
        for (level,title), count in sorted(collections.Counter((h['level'],h['title']) for h in headings).items()):
            if count > 1:
                warnings.append({'kind':'duplicate_heading','level':level,'title':title,'lines':[h['line'] for h in headings if h['level']==level and h['title']==title]})
        purpose_heads = [h for h in headings if h['level']==2 and h['title']=='Purpose']
        purpose = None
        if len(purpose_heads)!=1:
            warnings.append({'kind':'purpose_heading_count','count':len(purpose_heads)})
        if purpose_heads:
            h = purpose_heads[0]
            end = next((x['line']-1 for x in headings if x['line']>h['line'] and x['level']<=2), len(lines))
            purpose={'start_line':h['line'],'end_line':end,'raw':raw(h['line'],end),'raw_body':raw(h['line']+1,end)}
        cap_records=[]
        for h in reqs:
            end = next((x['line']-1 for x in headings if x['line']>h['line'] and x['level']<=3), len(lines))
            sc = [s for s in scenarios if h['line']<s['line']<=end]
            body_end=sc[0]['line']-1 if sc else end
            block, body=raw(h['line'],end),raw(h['line']+1,body_end)
            rec={'capability':path.parent.relative_to(root/'openspec/specs').as_posix(),'path':rel,'title':h['title'][len('Requirement:'):].strip(),'start_line':h['line'],'end_line':end,'body_start_line':h['line']+1,'body_end_line':body_end,'raw_body':body,'raw_block':block,'sha256':digest(block),'body_sha256':digest(body),'scenarios':[]}
            for s in sc:
                se=next((x['line']-1 for x in headings if x['line']>s['line'] and x['level']<=4),end+1)
                se=min(se,end)
                sb=raw(s['line'],se)
                rec['scenarios'].append({'title':s['title'][len('Scenario:'):].strip(),'start_line':s['line'],'end_line':se,'raw_block':sb,'sha256':digest(sb)})
            cap_records.append(rec)
        covered={s['start_line'] for r in cap_records for s in r['scenarios']}
        for s in scenarios:
            if s['line'] not in covered:
                warnings.append({'kind':'orphan_scenario','line':s['line']})
        records.extend(cap_records)
        files.append({'capability':path.parent.relative_to(root/'openspec/specs').as_posix(),'path':rel,'bytes':len(data),'characters':len(text),'lines':len(lines),'sha256':hashlib.sha256(data).hexdigest(),'requirements':len(reqs),'scenarios':len(scenarios),'purpose':purpose,'headings':headings,'warnings':warnings})
    totals={'capabilities':len(files),**{k:sum(f[k] for f in files) for k in ['bytes','characters','lines','requirements','scenarios']},'warnings':sum(len(f['warnings']) for f in files)}
    remote={'capabilities':34,'requirements':808,'scenarios':2165,'lines':13003,'characters':873110}
    payload={'head':head,'discovery':'sorted filesystem openspec/specs/**/spec.md','totals':totals,'remote_reference':remote,'remote_deltas':{k:totals[k]-v for k,v in remote.items()},'files':files}
    write_json(out/'inventory.json',payload)
    write_json(out/'requirements.json',records)
    with (out/'inventory.csv').open('w',encoding='utf-8',newline='') as f:
        fields=['capability','path','bytes','characters','lines','sha256','requirements','scenarios','warnings']
        writer=csv.DictWriter(f,fieldnames=fields)
        writer.writeheader()
        for item in files:
            row={k:item[k] for k in fields}
            row['warnings']=json.dumps(row['warnings'],ensure_ascii=False,sort_keys=True)
            writer.writerow(row)
    after=status()
    write_json(out/'execution.json',{'head':head,'status_before':before,'status_after':after,'elapsed_seconds':time.perf_counter()-start,'totals':totals})
    print(json.dumps(totals,sort_keys=True))

if __name__=='__main__':
    main()

