#!/usr/bin/env python3
"""Read-only duplicate/candidate analysis consuming inventory worker records.
Run: python3 candidates.py REQUIREMENTS_JSON OUTPUT_DIR
Normative body normalization: Unicode NFC, whitespace runs -> ASCII space, strip.
No punctuation/case/identifier removal; scenarios excluded. Lexical score is Jaccard
on lowercase ASCII alphanumeric identifier tokens >=3 chars after fixed stopwords.
Only cross-capability lexical pairs scored. Scores are candidates, never findings.
"""
import sys,json,pathlib,re,unicodedata,hashlib,itertools,csv,collections
src,out=map(pathlib.Path,sys.argv[1:]); out.mkdir(parents=True,exist_ok=True)
rs=json.loads(src.read_text());
if isinstance(rs,dict): rs=rs['requirements']
stop=set('the and shall not with from that this into when then only without after before their its for are has have was which through under while existing same other each one any all will may can an as be by if in is it of on or to a'.split())
def norm(x): return re.sub(r'\s+',' ',unicodedata.normalize('NFC',x)).strip()
def terms(r): return set(re.findall(r'[a-z0-9_]{3,}',(r['title']+' '+r['raw_body']).lower()))-stop
def evidence(r): return {k:r[k] for k in ('capability','path','title','start_line','end_line','body_start_line','body_end_line','raw_body','raw_block','sha256','body_sha256')}
pairs={}
def add(a,b,kind,**extra):
 k=tuple(sorted((rs.index(a),rs.index(b)))); p=pairs.setdefault(k,dict(left=evidence(a),right=evidence(b),triggers=[])); p['triggers'].append(kind);p.update(extra)
for kind,key in [('exact_title',lambda r:r['title']),('normalized_body',lambda r:norm(r['raw_body']))]:
 groups=collections.defaultdict(list)
 for r in rs: groups[key(r)].append(r)
 for value,group in sorted(groups.items()):
  if value and len(group)>1:
   for a,b in itertools.combinations(group,2): add(a,b,kind,normalized_sha256=hashlib.sha256(value.encode()).hexdigest())
ts=[terms(r) for r in rs];lex=[]
for i,a in enumerate(rs):
 for j in range(i+1,len(rs)):
  b=rs[j]
  if a['capability']==b['capability']: continue
  shared=ts[i]&ts[j]; union=ts[i]|ts[j]; score=len(shared)/len(union) if union else 0
  if score>=0.25 and len(shared)>=5: lex.append((score,i,j,sorted(shared)))
lex.sort(key=lambda x:(-x[0],rs[x[1]]['path'],rs[x[1]]['start_line'],rs[x[2]]['path'],rs[x[2]]['start_line']))
for score,i,j,shared in lex: add(rs[i],rs[j],'lexical',jaccard=round(score,8),shared_terms=shared)
result=sorted(pairs.values(),key=lambda p:(p['left']['path'],p['left']['start_line'],p['right']['path'],p['right']['start_line']))
for i,p in enumerate(result,1):p['id']=f'C{i:04}';p['review']='unreviewed'
(out/'candidates.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
with (out/'candidates.csv').open('w') as f:
 w=csv.writer(f);w.writerow(['id','left','right','triggers','jaccard','shared_terms'])
 for p in result:w.writerow([p['id'],f"{p['left']['path']}:{p['left']['start_line']}-{p['left']['end_line']}",f"{p['right']['path']}:{p['right']['start_line']}-{p['right']['end_line']}",'|'.join(p['triggers']),p.get('jaccard',''),' '.join(p.get('shared_terms',[]))])
summary={'requirements':len(rs),'pairs':len(result),'exact_title_pairs':sum('exact_title'in p['triggers'] for p in result),'normalized_body_pairs':sum('normalized_body'in p['triggers'] for p in result),'lexical_pairs':len(lex),'threshold':0.25,'min_shared_terms':5,'normalization':__doc__}
(out/'summary.json').write_text(json.dumps(summary,indent=2)+'\n'); print(json.dumps(summary))
print('TOP LEXICAL')
for score,i,j,shared in lex[:25]:print(round(score,3),rs[i]['capability'],rs[i]['title'],' || ',rs[j]['capability'],rs[j]['title'])

