import pathlib,re,json,urllib.parse,collections
root=pathlib.Path.cwd(); findings=[]; n=0
for p in sorted(root.glob('openspec/specs/**/spec.md')):
 text=p.read_text()
 for m in re.finditer(r'\[[^\]\n]+\]\(([^)\s]+)\)',text):
  dest=m.group(1)
  if re.match(r'\w+://',dest):continue
  n+=1; file,_,anchor=dest.partition('#'); target=(p.parent/urllib.parse.unquote(file)).resolve() if file else p
  status='ok'
  if not target.is_file():status='missing_file'
  elif anchor:
   anchors=[];counts=collections.Counter()
   for line in target.read_text().splitlines():
    h=re.match(r'^#{1,6}\s+(.*?)\s*#*$',line)
    if h:
     a=re.sub(r'[^\w\- ]','',h[1].lower()).replace(' ','-');suffix=counts[a];counts[a]+=1;anchors.append(a+(f'-{suffix}' if suffix else ''))
   if urllib.parse.unquote(anchor) not in anchors:status='missing_anchor'
  findings.append({'path':str(p.relative_to(root)),'line':text[:m.start()].count('\n')+1,'target':dest,'status':status})
out=root.__class__('/tmp/wfs-openspec-audit.Gst1Xs/overlap/links.json');out.write_text(json.dumps(findings,indent=2)+'\n');print(n,collections.Counter(x['status'] for x in findings))
for x in findings:
 if x['status']!='ok':print(x)
